<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\AcademicRules;
class ComplianceController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 private function item($level,$area,$title,$count,$route,$basis='local'){return compact('level','area','title','count','route','basis');}
 private function ruleTitle($key,$title){$s=AcademicRules::source($key);return $title.($s?->regulation_title?' · '.$s->regulation_title.($s->document_number?' №'.$s->document_number:''):'');}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$items=[];
 $unapproved=DB::table('curriculum_plans')->where('academic_period_id',$p->id)->where('approval_status','!=','approved')->count();if($unapproved)$items[]=$this->item('warning','Рабочие программы','Не утверждены рабочие программы',$unapproved,'curriculum.index');
 $tol=(float)AcademicRules::get('hours_tolerance',0);$def=0;$over=0;foreach((\Illuminate\Support\Facades\Schema::hasTable('load_requirements')?DB::table('load_requirements')->where('academic_period_id',$p->id)->get():collect()) as $h){$q=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$h->study_group_id,'subject_id'=>$h->subject_id]);if($h->study_type_id)$q->where('study_type_id',$h->study_type_id);$bal=(float)$h->required_hours-(float)$q->sum('hours_total');if($bal>$tol)$def++;if($bal<-$tol)$over++;}if($def)$items[]=$this->item('critical','Нагрузка',$this->ruleTitle('hours_tolerance',"Недораспределены часы сверх допуска {$tol}"),$def,'tarification.index');if($over)$items[]=$this->item('warning','Нагрузка',$this->ruleTitle('hours_tolerance',"Перераспределены часы сверх допуска {$tol}"),$over,'tarification.index');
 $vac=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'vacant'=>1])->count();if($vac)$items[]=$this->item('critical','Нагрузка','Нагрузка без преподавателя',$vac,'tarification.index');
 $week=(float)AcademicRules::get('teacher_weekly_hours_warning',0);if($week>0){$overTeachers=DB::table('teaching_load_plans')->where('academic_period_id',$p->id)->whereNotNull('teacher_id')->groupBy('teacher_id')->havingRaw('SUM(hours_week) > ?',[$week])->get()->count();if($overTeachers)$items[]=$this->item('warning','Нагрузка',$this->ruleTitle('teacher_weekly_hours_warning',"Недельная нагрузка выше контрольного порога {$week} ч."),$overTeachers,'tarification.index');}
 $debts=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where('sh.academic_period_id',$p->id)->whereRaw('a.attempt_no=(select max(a2.attempt_no) from attestation_attempts a2 where a2.attestation_sheet_id=a.attestation_sheet_id and a2.student_id=a.student_id)')->where('a.passed',0)->count();if($debts)$items[]=$this->item('critical','Аттестация','Незакрытые академические задолженности',$debts,'attestation.index','federal');
 $d1=(int)AcademicRules::get('retake_days',0);if($d1){$n=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where('sh.academic_period_id',$p->id)->where('a.attempt_no',0)->where('a.passed',0)->whereNotNull('a.completed_at')->where('a.completed_at','<',now()->subDays($d1))->whereNotExists(fn($q)=>$q->select(DB::raw(1))->from('attestation_attempts as r')->whereColumn('r.attestation_sheet_id','a.attestation_sheet_id')->whereColumn('r.student_id','a.student_id')->where('r.attempt_no','>',0))->count();if($n)$items[]=$this->item('critical','Аттестация',$this->ruleTitle('retake_days',"Не назначена 1-я пересдача > {$d1} дн."),$n,'attestation.index');}
 $d2=(int)AcademicRules::get('retake_second_days',0);if($d2){$n=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where('sh.academic_period_id',$p->id)->where('a.attempt_no',1)->where('a.passed',0)->whereNotNull('a.completed_at')->where('a.completed_at','<',now()->subDays($d2))->whereNotExists(fn($q)=>$q->select(DB::raw(1))->from('attestation_attempts as r')->whereColumn('r.attestation_sheet_id','a.attestation_sheet_id')->whereColumn('r.student_id','a.student_id')->where('r.attempt_no',2))->count();if($n)$items[]=$this->item('critical','Аттестация',$this->ruleTitle('retake_second_days',"Не назначена 2-я пересдача > {$d2} дн."),$n,'attestation.index');}
 $min=max(1,(int)AcademicRules::get('commission_min_members',1));$comm=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where('sh.academic_period_id',$p->id)->where('a.attempt_no',2)->whereRaw('(select count(*) from attestation_commission_members m where m.attestation_attempt_id=a.id) < ?',[$min])->count();if($comm)$items[]=$this->item('critical','Аттестация',$this->ruleTitle('commission_min_members',"Комиссия второй пересдачи: менее {$min} чел."),$comm,'attestation.index','federal');
 if(AcademicRules::get('practice_require_positive_result',true)){$practice=DB::table('practice_placements')->where('academic_period_id',$p->id)->where(fn($q)=>$q->whereNull('result')->orWhereNotIn('result',['passed','зачтено','5','4','3']))->count();if($practice)$items[]=$this->item('warning','Практика',$this->ruleTitle('practice_require_positive_result','Практика без положительного результата'),$practice,'practice.index');}
 $gia=DB::table('gia_student_results as gr')->join('gia_campaigns as gc','gc.id','=','gr.gia_campaign_id')->where('gc.academic_period_id',$p->id)->where('gr.admission_status','blocked')->count();if($gia)$items[]=$this->item('critical','ГИА','Выпускники заблокированы для ГИА',$gia,'gia.index');
 $grad=DB::table('graduation_records')->where('academic_period_id',$p->id)->where('readiness','blocked')->count();if($grad)$items[]=$this->item('critical','Выпуск','Выпускники не готовы к выпуску',$grad,'graduation.index');
 $critical=collect($items)->where('level','critical')->sum('count');$warnings=collect($items)->where('level','warning')->sum('count');$groups=DB::table('study_groups as g')->leftJoin('specialties as sp','sp.id','=','g.specialty_id')->where('g.active',1)->select('g.*','sp.code as specialty_code','sp.name as specialty_name')->orderBy('g.name')->get();foreach($groups as $g){$g->debts=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where(['sh.academic_period_id'=>$p->id,'sh.study_group_id'=>$g->id])->whereRaw('a.attempt_no=(select max(a2.attempt_no) from attestation_attempts a2 where a2.attestation_sheet_id=a.attestation_sheet_id and a2.student_id=a.student_id)')->where('a.passed',0)->count();$g->vacancies=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$g->id,'vacant'=>1])->count();$g->programs=DB::table('curriculum_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$g->id])->count();$g->unapproved=DB::table('curriculum_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$g->id])->where('approval_status','!=','approved')->count();}return view('academic-office.compliance',compact('p','items','critical','warnings','groups'));}
}